import "../../styles/index-base.css";
import "../../styles/components/checkbox.css";
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox";
import { Check, Minus } from "@phosphor-icons/react";
import { useId } from "react";
import { cn } from "../../lib/cn";

type CheckboxProps = CheckboxPrimitive.Root.Props & {
  label?: string;
  description?: string;
};

export function Checkbox({ className, label, description, id: providedId, ...props }: CheckboxProps) {
  const generatedId = useId();
  const id = providedId ?? generatedId;
  return (
    <div className="ix-choice-row">
      <CheckboxPrimitive.Root id={id} className={cn("ix-checkbox", className)} {...props}>
        <CheckboxPrimitive.Indicator className="ix-checkbox__indicator">
          <Check className="ix-checkbox__check" weight="bold" />
          <Minus className="ix-checkbox__mixed" weight="bold" />
        </CheckboxPrimitive.Indicator>
      </CheckboxPrimitive.Root>
      {label && (
        <label htmlFor={id} className="ix-choice-copy">
          <span>{label}</span>
          {description && <small>{description}</small>}
        </label>
      )}
    </div>
  );
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-choice-row { display: flex; align-items: flex-start; gap: 9px; }

.ix-choice-copy { display: grid; gap: 3px; color: var(--ix-ink); font-size: 13.5px; cursor: pointer; }

.ix-choice-copy small { color: var(--ix-ink-tertiary); font-size: 11.5px; font-weight: 400; line-height: 1.45; }

.ix-checkbox { position: relative; display: grid; width: 16px; height: 16px; flex: none; margin-top: 1px; padding: 0; place-items: center; border: 1px solid var(--ix-border-strong); border-radius: 4px; background: var(--ix-surface); color: var(--ix-on-inverse); cursor: pointer; transition: background var(--ix-hover-duration), border-color var(--ix-hover-duration), transform var(--ix-press-duration) var(--ix-ease-out); }

.ix-checkbox::after { position: absolute; inset: -8px; content: ""; }

.ix-checkbox[data-checked] { border-color: var(--ix-inverse); background: var(--ix-inverse); color: var(--ix-on-inverse); }

.ix-checkbox[data-indeterminate] { border-color: var(--ix-inverse); background: var(--ix-inverse); color: var(--ix-on-inverse); }

.ix-checkbox[data-disabled] { opacity: 0.42; cursor: not-allowed; }

.ix-checkbox:active:not([data-disabled]) { transform: scale(0.92); }

.ix-checkbox__indicator { display: grid; place-items: center; }

.ix-checkbox__indicator svg { width: 11px; height: 11px; }

.ix-checkbox__mixed { display: none; }

.ix-checkbox[data-indeterminate] .ix-checkbox__check { display: none; }

.ix-checkbox[data-indeterminate] .ix-checkbox__mixed { display: block; }

.ix-choice-row:has([data-disabled]) .ix-choice-copy { opacity: 0.48; cursor: not-allowed; }

@media (forced-colors: active) {
.ix-checkbox { forced-color-adjust: none; border-color: CanvasText; background: Canvas; color: CanvasText; }

.ix-checkbox[data-checked],
.ix-checkbox[data-indeterminate] { background: Highlight; color: HighlightText; }
}

:root[data-theme="dark"] .ix-checkbox[data-checked],
:root[data-theme="dark"] .ix-checkbox[data-indeterminate] { box-shadow: none; }

.ix-checkbox__indicator {
  opacity: 1;
  transform: scale(1);
  transition: opacity 140ms var(--ix-ease-out), transform 140ms var(--ix-ease-out);
}

@starting-style {
.ix-checkbox__indicator {
    opacity: 0;
    transform: scale(.72);
  }
}

@media (prefers-reduced-motion: reduce) {
.ix-checkbox__indicator { transition-duration: 0.01ms; }
}

@media (prefers-reduced-motion: reduce) {
.ix-checkbox:active:not([data-disabled]) { transform: none; }

.ix-checkbox__indicator { transition-duration: 0.01ms; }
}
}
